class useStrictTransformer(
    @kotlin.jvm.JvmField var transformer: Transformer = Transformer(),
    @kotlin.jvm.JvmField var compilerOptions: CompilerOptions? = null,
    @kotlin.jvm.JvmField var getEmitModuleFormatOfFile: ((HasFileName?) -> ModuleKind)? = null,
) {

    fun goCopy(): useStrictTransformer = useStrictTransformer(transformer = transformer.goCopy(), compilerOptions = compilerOptions, getEmitModuleFormatOfFile = getEmitModuleFormatOfFile)

    fun goSet(o: useStrictTransformer) {
        transformer = o.transformer.goCopy()
        compilerOptions = o.compilerOptions
        getEmitModuleFormatOfFile = o.getEmitModuleFormatOfFile
    }

    companion object {
        val ELEM: GoElem<useStrictTransformer> = GoElem({ useStrictTransformer() }, { it.goCopy() })
    }
}

